"""Fixed Guest platinum candidate: two PYZ modules, one known main, one template.

Root alone runs after source review. No payload/business/PyInstaller import,
Analysis/hooks, executable launch, database, production data or input overwrite.
Reuse finance-repack d630 data IO/comparator and three pinned official writers.
Those definitions retain their GPL-2.0-or-later WITH Bootloader-exception terms;
the output keeps complete COPYING and upstream source/copyright notices.
"""
import os, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
if (os.name!='nt' or os.path.normcase(str(ROOT))!=os.path.normcase('C:/xjy-work/xjy-web-stage1') or
    os.path.normcase(sys.executable)!=os.path.normcase('C:/Python314/python.exe') or
    not sys.flags.isolated or not sys.flags.no_site or not sys.flags.dont_write_bytecode or sys.flags.optimize):
    raise RuntimeError('Fixed actual Guest Python -I -B -S required; no Host execution')
import argparse, base64, hashlib, importlib.util, json, re, stat, struct, types
SELF=ROOT/'audit-tools/platinum-ledger-repack.py'
HELPER=ROOT/'audit-tools/finance-repack.py'
HELPER_SHA='d630f373911715b3ef5ee80e6fbaeaae838c1469ab53f44759813bc066cf69a7'
OLD_INVENTORY_SHA='e65660926f866f476603426dcbc28135c2fdb557a0c23f4e70b2dd3027620ac7'
OLD_SIDECAR_SHA='3fb61be8039ce507fd862643047cb62260ae53eda0d220bec4b434306cdfec81'
OLD_INVENTORY_B64=''
OLD_SIDECAR_B64=''
INVENTORY=ROOT/'project/desktop/legacy-source/ledger/inventory_dashboard.py'
SIDECAR=ROOT/'project/desktop/legacy-source/sidecar_release.py'
TEMPLATE=ROOT/'project/desktop/legacy-source/ledger/app/templates/stock.html'
TEMPLATE_MEMBER='_internal/app/templates/stock.html'

def bootstrap_pin(file,pin):
    if not file.is_relative_to(ROOT): raise RuntimeError('Owned bootstrap path required')
    for item in (file,*file.parents):
        s=item.lstat()
        if stat.S_ISLNK(s.st_mode) or getattr(s,'st_file_attributes',0)&0x400 or stat.S_ISREG(s.st_mode) and s.st_nlink!=1:
            raise RuntimeError('Linked bootstrap path refused')
    if not file.is_file() or file.stat().st_size>1024*1024 or hashlib.sha256(file.read_bytes()).hexdigest()!=pin:
        raise RuntimeError('Root-pinned bootstrap source required')

def source_inputs(m,args):
    old_finance,new_finance=m.source_inputs()
    old_inventory=base64.b64decode(OLD_INVENTORY_B64,validate=True)
    old_sidecar=base64.b64decode(OLD_SIDECAR_B64,validate=True)
    m.require(len(old_inventory)==18137 and m.sha(old_inventory)==OLD_INVENTORY_SHA,'FROZEN_OLD_INVENTORY_REQUIRED')
    m.require(len(old_sidecar)==37960 and m.sha(old_sidecar)==OLD_SIDECAR_SHA,'FROZEN_OLD_SIDECAR_REQUIRED')
    old={'finance':old_finance,'inventory_dashboard':old_inventory,'sidecar':old_sidecar}
    new={'finance':new_finance,'inventory_dashboard':m.pinned(INVENTORY,args.inventory_sha256),
         'sidecar':m.pinned(SIDECAR,args.sidecar_sha256)}
    template=m.pinned(TEMPLATE,args.template_sha256)
    m.require(new['inventory_dashboard']!=old_inventory and new['sidecar']!=old_sidecar,'KNOWN_SOURCE_REPLACEMENT_REQUIRED')
    return old,new,template

def known_codes(m,archive,rows,old,new):
    original={}; replacements={}
    for name in ('finance','inventory_dashboard'):
        matches=[r for r in rows if r['name']==name and r['type']==0]
        m.require(len(matches)==1,'EXACT_KNOWN_PYZ_MODULE_REQUIRED:'+name)
        original[name]=matches[0]['code']
    mains=[r for r in archive['rows'] if r['name']=='sidecar' and r['type']=='s']
    m.require(len(mains)==1,'EXACT_KNOWN_SIDECAR_MAIN_REQUIRED')
    original['sidecar']=m.load_marshaled(mains[0]['payload'],True)
    for name,code in original.items():
        m.require(type(code) is types.CodeType,'KNOWN_CODE_REQUIRED')
        m.assert_same_code(code,compile(old[name],code.co_filename,'exec',dont_inherit=True,optimize=0))
        replacements[name]=compile(new[name],code.co_filename,'exec',dont_inherit=True,optimize=0)
        m.require(m.fingerprint(code)!=m.fingerprint(replacements[name]),'KNOWN_CODE_MUST_CHANGE:'+name)
    m.require(original['sidecar'].co_filename=='sidecar.py','PROVED_MAIN_FILENAME_REQUIRED')
    return original,replacements

def verify_pyz(m,before,after,replacements):
    m.require([(r['name'],r['type']) for r in before]==[(r['name'],r['type']) for r in after],'ORDERED_PYZ_METADATA_CHANGED')
    unknown=[]; namespaces=0; known=[]
    for left,right in zip(before,after):
        name=left['name']
        if left['type']==3:
            m.require(left['code'] is None and right['code'] is None,'NAMESPACE_CHANGED'); namespaces+=1
        elif name in ('finance','inventory_dashboard'):
            m.assert_same_code(replacements[name],right['code'])
            known.append({'name':name,'filename':right['code'].co_filename,'optimize':0,'dontInherit':True,
                          'oldStructureSha256':m.fingerprint(left['code']),'newStructureSha256':m.fingerprint(right['code'])})
        else:
            m.assert_same_code(left['code'],right['code'])
            unknown.append({'name':name,'type':left['type'],'structureSha256':m.fingerprint(left['code'])})
    m.require(len(unknown)==925 and namespaces==6 and len(known)==2,'ALL_933_PYZ_MEMBERS_REQUIRED')
    return {'pyzEntries':len(before),'unknownCodeObjectsVerified':925,'namespacesVerified':6,
            'codeFields':list(m.FIELDS),'unknownCodeProof':unknown,'knownPyz':known}

def verify_exe(m,original,candidate,old_codes,new_codes):
    m.require(len(original)==8520018 and m.sha(original)==m.PINS['exe'],'PINNED_ORIGINAL_EXE_REQUIRED')
    before,after=m.archive(original),m.archive(candidate)
    m.require(before['prefix'][:352]+before['prefix'][356:]==after['prefix'][:352]+after['prefix'][356:],'PE_PREFIX_EXCEPT_CHECKSUM_CHANGED')
    m.require(after['pe']['checksum']==m.checksum(candidate),'PE_CHECKSUM_INVALID')
    m.require(before['version']==after['version'] and before['library']==after['library'],'COOKIE_IDENTITY_CHANGED')
    meta=lambda r:(r['name'],r['type'],r['flag'])
    m.require([meta(r) for r in before['rows']]==[meta(r) for r in after['rows']],'ORDERED_CARCHIVE_METADATA_CHANGED')
    entries=[]; main=0
    for left,right in zip(before['rows'],after['rows']):
        if left['name']=='sidecar' and left['type']=='s':
            old_main=m.load_marshaled(left['payload'],True); new_main=m.load_marshaled(right['payload'],True)
            m.assert_same_code(old_main,old_codes['sidecar']); m.assert_same_code(new_main,new_codes['sidecar']); main+=1
        elif left['type']!='z':
            m.require(left['payload']==right['payload'],'OTHER_CARCHIVE_PAYLOAD_CHANGED:'+left['name'])
        entries.append({'name':left['name'],'type':left['type'],'flag':left['flag'],
                        'oldPayloadSha256':m.sha(left['payload']),'newPayloadSha256':m.sha(right['payload'])})
    m.require(main==1,'ONE_KNOWN_MAIN_REQUIRED')
    proof=verify_pyz(m,m.pyz(before['pyz']),m.pyz(after['pyz']),new_codes)
    proof.update(originalExeSha256=m.sha(original),candidateExeSha256=m.sha(candidate),candidateSize=len(candidate),
                 carchiveEntries=entries,prefixLength=len(before['prefix']),checksumOffset=352,
                 prefixExceptChecksumIdentical=True,checksum=after['pe']['checksum'],
                 main={'name':'sidecar','filename':new_codes['sidecar'].co_filename,'optimize':0,'dontInherit':True,
                       'oldStructureSha256':m.fingerprint(old_codes['sidecar']),'newStructureSha256':m.fingerprint(new_codes['sidecar'])})
    return proof

def build(m,args,admission):
    run=ROOT/'release-work'/args.run_id; created=False
    try:
        m.ordinary(run.parent); m.require(not run.exists() and not run.is_symlink() and not os.path.isjunction(run),'CREATE_NEW_RUN_REQUIRED')
        inputs=m.manifest_inputs(); old,new,template=source_inputs(m,args)
        original=m.pinned(m.ORIGINAL/'xjy-ledger/xjy-ledger.exe',m.PINS['exe'])
        archive=m.archive(original); rows=m.pyz(archive['pyz']); old_codes,new_codes=known_codes(m,archive,rows,old,new)
        m.require(TEMPLATE_MEMBER in inputs['ledger'] and m.sha(template)!=inputs['ledger'][TEMPLATE_MEMBER][1],'FIXED_EXTERNAL_TEMPLATE_REPLACEMENT_REQUIRED')
        zlib_writer,payload_writer,writer_evidence,bodies=m.load_writers()
        m.mkdir_new(run); created=True
        m.write_json(run/'.owner.json',{'purpose':'platinum-ledger-minimal-repack','runId':args.run_id,'toolSha256':args.tool_sha256},run)
        m.write_new(run/'PyInstaller-COPYING.txt',bodies['COPYING.txt'],run)
        notices=['PyInstaller 6.22.3; commit '+m.UPSTREAM_COMMIT,'Reuse of d630 exact three official AST definitions; no Analysis/hooks/whole-module import.',
                 'Platinum adapter replaces only two reviewed PYZ modules, one reviewed main and one external template.']
        for name in ('PyInstaller/archive/writers.py','PyInstaller/building/utils.py'):
            notices.extend(['',name,*bodies[name].decode('utf-8').splitlines()[:10]])
        m.write_new(run/'PyInstaller-source-notice.txt',('\n'.join(notices)+'\n').encode(),run)
        entries=[]; code_dict={}
        for row in rows:
            name,kind=row['name'],row['type']; entries.append((name,None if kind==3 else '__init__.py' if kind==1 else 'module.py','PYMODULE'))
            if kind!=3: code_dict[name]=new_codes[name] if name in ('finance','inventory_dashboard') else row['code']
        m.writer_new(zlib_writer,run/'platinum.pyz',run,entries,code_dict)
        pyz_bytes=m.stable(run/'platinum.pyz'); verify_pyz(m,rows,m.pyz(pyz_bytes),new_codes)
        payloads=[(r['name'],pyz_bytes if r['type']=='z' else m.marshal.dumps(new_codes['sidecar']) if r['name']=='sidecar' and r['type']=='s' else r['payload'],r['flag'],r['type']) for r in archive['rows']]
        m.writer_new(payload_writer,run/'platinum.pkg',run,payloads,'python314.dll')
        candidate=bytearray(archive['prefix']+m.stable(run/'platinum.pkg')); m.require(len(candidate)<=m.MAX_FILE,'CANDIDATE_SIZE_LIMIT')
        struct.pack_into('<I',candidate,352,m.checksum(candidate)); candidate=bytes(candidate)
        proof=verify_exe(m,original,candidate,old_codes,new_codes)
        modules=run/'modules-input'; m.mkdir_new(modules); expected={}; copied=[]; changed=[]
        for module_id,(directory,count,total) in m.MODULES.items():
            expected[module_id]=dict(inputs[module_id])
            for name,(size,digest) in inputs[module_id].items():
                original_bytes=m.stable(m.ORIGINAL/directory/name)
                m.require((len(original_bytes),m.sha(original_bytes))==(size,digest),'COPY_INPUT_CHANGED:'+name)
                body=candidate if module_id=='ledger' and name=='xjy-ledger.exe' else template if module_id=='ledger' and name==TEMPLATE_MEMBER else original_bytes
                m.write_new(modules/directory/name,body,run); expected[module_id][name]=(len(body),m.sha(body))
                if body!=original_bytes: changed.append({'module':module_id,'path':name,'oldSha256':digest,'newSha256':m.sha(body)})
                copied.append({'module':module_id,'path':name,'size':len(body),'sha256':m.sha(body)})
            m.require(m.tree(modules/directory)==expected[module_id],'COMPLETE_COPY_MISMATCH:'+module_id)
        m.require(len(copied)==496 and {(r['module'],r['path']) for r in changed}=={('ledger','xjy-ledger.exe'),('ledger',TEMPLATE_MEMBER)},'ONLY_TWO_OF_496_PROGRAM_FILES_MAY_CHANGE')
        manifest=json.loads(m.pinned(m.MANIFEST,m.PINS['manifest']),object_pairs_hook=m.unique_object)
        for module in manifest['modules']:
            actual=expected[module['id']]
            for row in module['files']: row['size'],row['sha256']=actual[row['path']]
            module['size'],module['sha256']=actual[module['file']]
        m.write_json(modules/'manifest.json',manifest,run)
        manifest_bytes=m.stable(modules/'manifest.json'); reread=json.loads(manifest_bytes,object_pairs_hook=m.unique_object)
        m.require(reread==manifest,'NEW_MANIFEST_READBACK_CHANGED')
        for module in reread['modules']:
            directory=m.MODULES[module['id']][0]; actual=m.tree(modules/directory)
            m.require(actual=={r['path']:(r['size'],r['sha256']) for r in module['files']},'NEW_MANIFEST_DOES_NOT_MATCH_ACTUAL_TREE')
        m.require(verify_exe(m,original,m.stable(modules/'xjy-ledger/xjy-ledger.exe'),old_codes,new_codes)==proof,'REOPENED_EXE_PROOF_CHANGED')
        m.require(m.manifest_inputs()==inputs and source_inputs(m,args)==(old,new,template),'ORIGINAL_OR_REVIEWED_SOURCE_CHANGED')
        m.require(m.writer_sources()==bodies,'OFFICIAL_WRITER_SOURCE_CHANGED')
        m.pinned(HELPER,HELPER_SHA); m.pinned(SELF,args.tool_sha256); m.pinned(m.GUARD,m.PINS['guard']); m.pinned(m.VALIDATOR,m.PINS['validator'])
        expected_flat={'manifest.json':(len(manifest_bytes),m.sha(manifest_bytes))}
        for module_id,(directory,count,total) in m.MODULES.items():
            expected_flat.update({directory+'/'+name:identity for name,identity in expected[module_id].items()})
        m.require(m.tree(modules)==expected_flat,'FINAL_MODULES_INPUT_TREE_CHANGED_OR_EXTRA_FILES')
        proof.update(changedProgramFiles=changed,programFileCount=496,unchangedOriginalProgramFiles=494,
                     sourcePins={'oldFinance':m.PINS['oldFinance'],'newFinance':m.PINS['finance'],'oldInventory':OLD_INVENTORY_SHA,'newInventory':args.inventory_sha256,
                                 'oldSidecar':OLD_SIDECAR_SHA,'newSidecar':args.sidecar_sha256,'newTemplate':args.template_sha256},
                     archivePayloadExecuted=False,businessModulesImported=False,originalInputsUnchanged=True)
        m.write_json(run/'candidate-proof.json',proof,run)
        result={'purpose':'platinum-ledger-minimal-repack','state':'ACTUAL_GUEST_CANDIDATE','passed':True,'runId':args.run_id,
                'modulesInput':str(modules),'manifestSha256':m.sha(m.stable(modules/'manifest.json')),'proofSha256':m.sha(m.stable(run/'candidate-proof.json')),
                'toolSha256':args.tool_sha256,'repackerSha256':HELPER_SHA,'actualContext':admission,'writerEvidence':writer_evidence,
                'programFileCount':496,'changedProgramFiles':changed,'manifestAdditionalMetadata':True,
                'originalInputsUnchanged':True,'archivePayloadExecuted':False,'businessModulesImported':False,'executableLaunched':False,
                'analysisOrHooksRun':False,'wholePyinstallerImported':False,'productionDataAccessed':False,'formalReleaseAuthorized':False}
        m.write_json(run/'result.json',result,run); return result
    except Exception as error:
        if created: m.write_json(run/'failure.json',{'passed':False,'errorType':type(error).__name__,'error':str(error),'failedOutputRetained':True},run)
        raise

def main():
    p=argparse.ArgumentParser(description=__doc__,allow_abbrev=False)
    for name in ('tool-sha256','inventory-sha256','sidecar-sha256','template-sha256'): p.add_argument('--'+name,required=True)
    p.add_argument('--run-id',required=True); args=p.parse_args()
    if not all(re.fullmatch('[0-9a-f]{64}',getattr(args,name)) for name in ('tool_sha256','inventory_sha256','sidecar_sha256','template_sha256')):
        raise RuntimeError('Four explicit Root-reviewed SHA256 pins required')
    if not re.fullmatch('platinum-ledger-repack-[a-z0-9][a-z0-9-]{0,39}',args.run_id): raise RuntimeError('Fixed bounded CreateNew run name required')
    bootstrap_pin(SELF,args.tool_sha256); bootstrap_pin(HELPER,HELPER_SHA)
    spec=importlib.util.spec_from_file_location('platinum_fixed_repack_helper',HELPER); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    admission=m.admit(HELPER_SHA); m.pinned(SELF,args.tool_sha256)
    result=build(m,args,admission)
    print(json.dumps({key:result[key] for key in ('passed','modulesInput','manifestSha256','proofSha256','programFileCount','changedProgramFiles')})); return 0

if __name__=='__main__':
    try: raise SystemExit(main())
    except Exception as error:
        print(json.dumps({'passed':False,'errorType':type(error).__name__,'error':str(error),'formalReleaseAuthorized':False})); raise SystemExit(1)
